286	/// Whether `label` can be written as a markdown footnote label, `[^label]`.
287	///
288	/// Only what would break the syntax is refused: whitespace, `[`, `]` and `^`.
289	/// `notes.md`, `session:abc` and `a/b` are valid labels, and refusing them made
290	/// pk rewrite an id the body had already cited with — pk breaking a citation the
291	/// model had got right.
292	fn is_footnote_label(label: &str) -> bool {
293	    !label.is_empty()
294	        && !label
295	            .chars()
296	            .any(|c| c.is_whitespace() || matches!(c, '[' | ']' | '^'))
297	}
