299	/// Give every source an id that is unique within the entry (OKF v0.2 §5.1: the
300	/// footnote join is by label, so a duplicate misattributes silently).
301	///
302	/// The model discovers the sources and cites with labels of its own choosing,
303	/// so a usable label is kept exactly as given — re-deriving it would leave the
304	/// footnote in the body matching nothing. Labels are claimed in three ordered
305	/// passes, because anything pk invents must never take a label the model
306	/// chose, wherever in the list that label appears:
307	///
308	/// 1. the first occurrence of every distinct label the model chose;
309	/// 2. repeats of a label, which get `-2`, `-3`…;
310	/// 3. labels derived from `resource`, for a source with none or an unusable one.
311	///
312	/// Doing 1 and 2 together let a suffix take a label cited further down (`x`,
313	/// `x`, `x-2`: the second `x` became `x-2`), and doing 3 before 1 let a
314	/// derived label do the same. Labels compare case-folded: markdown resolves
315	/// `[^Doc]` against `[^doc]:`.
316	fn with_unique_ids(sources: Vec<Source>) -> Vec<Source> {
317	    use std::collections::HashSet;
318	
319	    fn claim_free(base: &str, taken: &mut HashSet<String>) -> String {
320	        let mut n = 1_u32;
321	        loop {
322	            let candidate = if n == 1 {
323	                base.to_owned()
324	            } else {
325	                format!("{base}-{n}")
326	            };
327	            if taken.insert(candidate.to_lowercase()) {
328	                return candidate;
329	            }
330	            n += 1;
331	        }
332	    }
333	
334	    let chosen: Vec<Option<&str>> = sources
335	        .iter()
336	        .map(|source| {
337	            source
338	                .id
339	                .as_deref()
340	                .filter(|label| is_footnote_label(label))
341	        })
342	        .collect();
343	    let mut taken: HashSet<String> = HashSet::new();
344	    let mut ids: Vec<Option<String>> = vec![None; sources.len()];
345	
346	    for (slot, label) in ids.iter_mut().zip(&chosen) {
347	        if let Some(label) = label {
348	            if taken.insert(label.to_lowercase()) {
349	                *slot = Some((*label).to_owned());
350	            }
351	        }
352	    }
353	    for (slot, label) in ids.iter_mut().zip(&chosen) {
354	        if let (None, Some(label)) = (&slot, label) {
355	            *slot = Some(claim_free(label, &mut taken));
356	        }
357	    }
358	    for (slot, source) in ids.iter_mut().zip(&sources) {
359	        if slot.is_none() {
360	            let derived = ArticleId::from_slug(&source.resource).0;
361	            let base = if is_footnote_label(&derived) {
362	                derived.as_str()
363	            } else {
364	                "source"
365	            };
366	            *slot = Some(claim_free(base, &mut taken));
367	        }
368	    }
369	
370	    sources
371	        .into_iter()
372	        .zip(ids)
373	        .map(|(source, id)| Source { id, ..source })
374	        .collect()
375	}
