65	    for e in entries {
66	        let group = e
67	            .entry_type
68	            .clone()
69	            .unwrap_or_else(|| "Uncategorized".to_string());
70	        groups.entry(group).or_default().push(e);
71	    }
72	
73	    let mut out = String::new();
